contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address recipient) public {
        require(recipient != address(0));
        bool reverted;
        uint256 balBefore = address(c).balance;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted == (caller != c.owner()) || address(c).balance == balBefore);
    }

    receive() external payable {}
}

