contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        uint256 cBalanceBefore = address(c).balance;
        uint256 senderBalanceBefore = address(this).balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = address(c).balance;
        uint256 senderBalanceAfter = address(this).balance;

        assert(reverted || (cBalanceAfter == 0 && senderBalanceAfter == senderBalanceBefore + cBalanceBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        require(address(c).balance > 0, "c must have a nonzero balance");

        bool reverted;
        if (recipient == address(this)) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted && address(c).balance > 0);
        } else {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted && address(c).balance == 0);
        }
    }

    receive() external payable {}
}

